function hydrate(p: CsvRoleBandPacked): CsvRoleBand {
  return {
    totalMinLpa: p.a,
    totalMedianLpa: p.b,
    totalMaxLpa: p.c,
    fixedMinLpa: p.d,
    fixedMaxLpa: p.e,
    bonusMinLpa: p.f,
    bonusMaxLpa: p.g,
    equityMinLpa: p.h,
    equityMaxLpa: p.i,
    joiningBonusMinLpa: p.j,
    joiningBonusMaxLpa: p.k,
    equityType: T_EQUITY_TYPE[p.H],
    vestingSchedule: T_VESTING[p.I],
    equityLiquidityRisk: T_LIQUIDITY[p.J],
    noticePeriod: T_NOTICE[p.K],
    bestNegotiationFocus: T_BEST_NEG_FOCUS[p.L],
    likelyHrPushback: T_HR_PUSHBACK[p.C],
    candidateQuestionsToVerify: T_QUESTIONS[p.S] as string[],
    candidateRedFlags: T_RED_FLAGS[p.A],
    supportedInterviewFocus: T_SUPPORTED_FOCUS[p.T] as string[],
    safeAskMinLpa: p.l,
    safeAskMaxLpa: p.m,
    strongAskMinLpa: p.n,
    strongAskMaxLpa: p.o,
    stretchAskMinLpa: p.p,
    stretchAskMaxLpa: p.q,
    walkawayThresholdLpa: p.r,
    candidateBestResponse: T_BEST_RESP[p.D],
    candidateBadResponse: T_BAD_RESP[p.E],
    hrFollowupQuestion: T_HR_FOLLOWUP[p.F],
    salaryNegotiationRubric: T_RUBRIC[p.G],
    benefitsSummary: T_BENEFITS[p.B],
    locationMultiplierMin: p.s,
    locationMultiplierMax: p.t,
    experienceRange: T_EXPERIENCE[p.R],
    companyType: T_COMPANY_TYPE[p.M],
    roleFamily: T_ROLE_FAMILY[p.N],
    roleSubfamily: T_ROLE_SUBFAMILY[p.O],
    likelyIndiaLocations: T_LOCATIONS[p.P],
    v6PrimaryInterviewFocus: T_PRIMARY_FOCUS[p.Q],
  };
}

function hydrateCompany(packed: CsvCompanyPacked): CsvCompany {
  const roles: Record<string, Partial<Record<CsvLevel, CsvRoleBand>>> = {};
  for (const role of Object.keys(packed.roles)) {
    const lvls = packed.roles[role];
    const out: Partial<Record<CsvLevel, CsvRoleBand>> = {};
    for (const lvl of Object.keys(lvls) as CsvLevel[]) {
      const p = lvls[lvl];
      if (p) out[lvl] = hydrate(p);
    }
    roles[role] = out;
  }
  return {
    companyName: packed.companyName,
    companyType: T_COMPANY_TYPE[packed.companyTypeId],
    roles,
  };
}

const HYDRATED_CACHE: Record<string, CsvCompany> = {};
function getHydratedByKey(key: string): CsvCompany | null {
  const cached = HYDRATED_CACHE[key];
  if (cached) return cached;
  const packed = PACKED[key];
  if (!packed) return null;
  const h = hydrateCompany(packed);
  HYDRATED_CACHE[key] = h;
  return h;
}

export const CSV_COMPANY_ROLE_BANDS: Record<string, CsvCompany> = new Proxy(
  {} as Record<string, CsvCompany>,
  {
    get(_target, prop: string) {
      if (typeof prop !== "string") return undefined;
      return getHydratedByKey(prop) ?? undefined;
    },
    has(_target, prop: string) {
      return typeof prop === "string" && prop in PACKED;
    },
    ownKeys() {
      return Object.keys(PACKED);
    },
    getOwnPropertyDescriptor(_target, prop: string) {
      if (typeof prop !== "string" || !(prop in PACKED)) return undefined;
      return {
        enumerable: true,
        configurable: true,
        value: getHydratedByKey(prop),
      };
    },
  },
);

function normalizeCompanyKey(name: string): string {
  let k = name.toLowerCase().trim();
  k = k.replace(/[.,;:!?]+$/g, "").trim();
  if (k.endsWith(" india")) k = k.slice(0, -" india".length).trim();
  return k;
}

export function getCsvCompanyBand(company: string | undefined | null): CsvCompany | null {
  if (!company) return null;
  const key = normalizeCompanyKey(company);
  if (!key) return null;
  const direct = getHydratedByKey(key);
  if (direct) return direct;
  const withIndia = getHydratedByKey(key + " india");
  if (withIndia) return withIndia;
  return null;
}

export function getCsvRoleLevelBand(
  company: string | undefined | null,
  role: string | undefined | null,
  level: CsvLevel | undefined | null,
): CsvRoleBand | null {
  if (!company || !role || !level) return null;
  const co = getCsvCompanyBand(company);
  if (!co) return null;
  const exact = co.roles[role];
  if (exact) {
    const band = exact[level];
    if (band) return band;
  }
  const target = role.toLowerCase().trim();
  for (const k of Object.keys(co.roles)) {
    if (k.toLowerCase().trim() === target) {
      const band = co.roles[k][level];
      if (band) return band;
    }
  }
  return null;
}
